<?php use Dilemma\Content; use Dilemma\Config; $name = ltrim($path, '/'); ?>
<article class="reading"><h1><?= $t($name) ?></h1><?php if (in_array($name, ['privacy', 'terms'], true)): ?><p class="notice"><?= $t('legal_review') ?></p><?php if (Config::get('LEGAL_OWNER') !== ''): ?><p><?= $e(Config::get('LEGAL_OWNER')) ?></p><?php endif; ?><?php if (Config::get('PRIVACY_CONTACT') !== ''): ?><p><a href="mailto:<?= $e(Config::get('PRIVACY_CONTACT')) ?>"><?= $e(Config::get('PRIVACY_CONTACT')) ?></a></p><?php endif; ?><?php endif; ?><?php foreach (Content::sections($name) as $section): ?><section><h2><?= $e($section['title']) ?></h2><p><?= $e($section['text']) ?></p></section><?php endforeach; ?><?php if ($name === 'how'): ?><a class="button" href="<?= $user ? '/new' : '/login?register=1' ?>"><?= $t('new_debate') ?> ↗</a><?php endif; ?></article>
